const Icon = ({ name, size = 20, className = "", fill = "none" }) => {
    const iconRef = useRef(null);
    useEffect(() => {
        if (window.lucide) {
            window.lucide.createIcons({
                root: iconRef.current ? iconRef.current.parentNode : document,
                nameAttr: 'datalucide',
                attrs: { class: className, width: size, height: size, stroke: "currentColor", fill: fill }
