const AuthScreen = ({ onAuthSuccess }) => {
    const [isLogin, setIsLogin] = useState(true);
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [name, setName] = useState("");
    const [error, setError] = useState("");

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError("");
        try {
            if (isLogin) {
                const formData = new FormData();
                formData.append('username', email);
                formData.append('password', password);
                const res = await fetch(${API_BASE}/token, { method: 'POST', body: formData });
                if (!res.ok) throw new Error("Hibás email vagy jelszó");
                const data = await res.json();
                localStorage.setItem('token', data.access_token);
                onAuthSuccess();
            } else {
                const res = await fetch(${API_BASE}/api/register, {
                    method: 'POST',
                    headers: { 'ContentType': 'application/json' },
                    body: JSON.stringify({ email, password, full_name: name })
                });
                if (!res.ok) throw new Error("A regisztráció sikertelen. Lehet, hogy az email már foglalt.");
                setIsLogin(true);
            }
        } catch (err) { setError(err.message); }
    };

    return (
        <div className="flex itemscenter justifycenter hscreen bgapplebg p6 animatefadein">
            <div className="wfull maxwsm bgapplesurface border borderappleborder rounded2xl p8 shadow2xl">
                <div className="flex justifycenter mb6">
                    <div className="w16 h16 bgappleblue/20 rounded2xl flex itemscenter justifycenter">
                        <Icon name="terminal" size={32} className="textappleblue" />
                    </div>
                </div>
