                <p className="textcenter textapplesubtext textsm mb8">{isLogin ? "Jelentkezz be a folytatáshoz" : "Kezdd el a fejlesztést még ma"}</p>

                {error && <div className="mb4 p3 bgred500/10 border borderred500/20 textred500 textxs roundedlg">{error}</div>}

                <form onSubmit={handleSubmit} className="spacey4">
                    {!isLogin && (
                        <div className="spacey1">
                            <label className="textxs fontmedium textapplesubtext uppercase ml1">Teljes név</label>
                            <input type="text" value={name} onChange={e => setName(e.target.value)} className="wfull bgapplebg border borderappleborder roundedxl p3 textappletext outlinenone focus:borderappleblue transitioncolors" required />
                        </div>
                    )}
                    <div className="spacey1">
                        <label className="textxs fontmedium textapplesubtext uppercase ml1">Email</label>
                        <input type="email" value={email} onChange={e => setEmail(e.target.value)} className="wfull bgapplebg border borderappleborder roundedxl p3 textappletext outlinenone focus:borderappleblue transitioncolors" required />
                    </div>
                    <div className="spacey1">
                        <label className="textxs fontmedium textapplesubtext uppercase ml1">Jelszó</label>
                        <input type="password" value={password} onChange={e => setPassword(e.target.value)} className="wfull bgapplebg border borderappleborder roundedxl p3 textappletext outlinenone focus:borderappleblue transitioncolors" required />
                    </div>
                    <button type="submit" className="wfull bgappleblue hover:bgappleblueActive textwhite fontsemibold py3.5 roundedxl transitionall active:scale[0.98] shadowlg shadowappleblue/20 mt2">
                        {isLogin ? "Bejelentkezés" : "Regisztráció"}
                    </button>
                </form>
                <div className="mt6 textcenter">
                    <button onClick={() => setIsLogin(!isLogin)} className="textsm textapplesubtext hover:textappletext transitioncolors">
                        {isLogin ? "Nincs még fiókod? Regisztrálj" : "Már van fiókod? Belépés"}
                    </button>
                </div>
            </div>
