const IDE = ({ project, onBack }) => {
    const [activeTab, setActiveTab] = useState('agent');
    const [activeFile, setActiveFile] = useState(null);
    const [files, setFiles] = useState([]);
    const [fileContent, setFileContent] = useState('');
    const [terminalOutput, setTerminalOutput] = useState([]);
    const [isSidebarOpen, setSidebarOpen] = useState(false);
    const [isToolsOpen, setToolsOpen] = useState(false);
    const [agentMessages, setAgentMessages] = useState([]);
    const [ws, setWs] = useState(null);

    useEffect(() => {
        loadFiles();
        const websocket = new WebSocket(${window.location.protocol === 'https:' ? 'wss' : 'ws'}://${window.location.host}/ws/${project.id});
        websocket.onmessage = (event) => {
            const data = JSON.parse(event.data);
            if (data.type === 'file_update') loadFiles();
        };
        setWs(websocket);
        return () => websocket.close();
    }, []);

    const loadFiles = async () => {
        const res = await fetch(${API_BASE}/api/projects/${project.id}/files, { headers: { 'Authorization': Bearer ${localStorage.getItem('token')} } });
        const data = await res.json();
        setFiles(data.files);
        if(!activeFile && data.files.length > 0) loadFile(data.files[0].name, false);
    };

    const loadFile = async (filename, switchTab = true) => {
        const res = await fetch(${API_BASE}/api/projects/${project.id}/file?name=${filename}, { headers: { 'Authorization': Bearer ${localStorage.getItem('token')} } });
        const data = await res.json();
        setActiveFile(filename);
        setFileContent(data.content);
        if (switchTab) { setActiveTab('editor'); setSidebarOpen(false); }
    };

    const saveFile = async (content) => {
        setFileContent(content);
        await fetch(${API_BASE}/api/projects/${project.id}/file?name=${activeFile}, {
            method: 'POST',
            headers: { 'ContentType': 'application/json', 'Authorization': Bearer ${localStorage.getItem('token')} },
            body: JSON.stringify({ content })
        });
    };

    const handleRun = async () => {
        setTerminalOutput(prev => [...prev, > ${activeFile} futtatása...]);
        setActiveTab('console');
        const res = await fetch(${API_BASE}/api/terminal/exec, {
            method: 'POST',
            headers: { 'ContentType': 'application/json', 'Authorization': Bearer ${localStorage.getItem('token')} },
            body: JSON.stringify({ command: run ${activeFile} })
        });
        const data = await res.json();
        setTerminalOutput(prev => [...prev, data.output]);
    };

    const handleAgentChat = async (message) => {
        const newMessage = { role: 'user', content: message };
        setAgentMessages(prev => [...prev, newMessage]);
        const res = await fetch(${API_BASE}/api/ai/chat, {
            method: 'POST',
            headers: { 'ContentType': 'application/json', 'Authorization': Bearer ${localStorage.getItem('token')} },
            body: JSON.stringify({ message, project_id: project.id })
        });
        const data = await res.json();
        setAgentMessages(prev => [...prev, { role: 'assistant', content: data.response }]);
        loadFiles();
